INSERT INTO cd_laravel.forms
(id, name, `key`, description, body_template, header_template, footer_template, custom_render_options, other_information, module, documenso_template_id, visibility, `type`, status, created_by, updated_by, deleted_by, created_at, updated_at, deleted_at)
VALUES('8ee639ae-5256-4256-b17e-f2356be46130', 'Admission Agreement', 'signed_admission_agreement', NULL, '<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Document</title>
  </head>
  <body>
    <style>
      * {
        font-family: Arial, sans-serif;
        margin: 0;
        padding: 0;
      }

      :root {
        font-size: 2px; /* 1rem = ?px ,  para pruebas mantener en 1px, para produccion/pdf mantener en 2px*/
      }

      .page {
        position: relative;
        width: 100%;
        height: 792rem;
      }

      p,
      li,
      span,
      input {
        font-size: 14rem;
        color: #3f3f46;
      }

      input[type="checkbox"] {
        width: 15rem;
        height: 15rem;
      }

      .checkbox-documenso {
        margin-left: 80px;
      }

      .page-break {
        page-break-before: always;
      }
    </style>

    <!--large-header Classes---------------------------------------------------------------------------->
    <style>
      /* Contenedor principal del header */
      .large-header-container {
        position: relative;
        width: 100%;
        height: 62rem;
      }

      /* Líneas superior e inferior de color azul */
      .large-header-topLine {
        position: absolute;
        background-color: #4f81ee;
        height: 5rem;
        width: 100%;
      }

      .large-header-bottomLine {
        position: absolute;
        bottom: 0px;
        background-color: #4f81ee;
        height: 1rem;
        width: 100%;
      }

      /* Área que contendrá las semiesferas, el logo y los títulos */
      .large-header-background {
        display: flex;
        flex-direction: row;
        justify-content: space-between;
        height: 62rem;
      }

      /* Semiesferas posicionadas a la izquierda */
      .large-header-semiCircles {
        position: relative;
        max-height: 62rem;
        width: 130rem;
      }

      .large-header-semiCircles > div {
        position: absolute;
        left: 0rem;
      }

      /* Logo posicionado a la derecha */
      .large-header-logo {
        position: relative;
        height: 24rem;
        width: 130rem;
      }

      .large-header-logo > div {
        position: absolute;
        top: 19rem;
        left: -30rem;
      }

      /* Títulos */

      .large-header-titles-container {
        position: relative;
      }

      .large-header-titles-container > div {
        position: relative;
        top: 17rem;
      }

      /* Título principal */
      .large-header-title {
        position: relative;
        text-align: center;
        margin: 0;
        font-weight: 700;
        font-size: 12rem;
        color: #4f81ee;
      }

      .large-header-title > div {
        position: absolute;
        top: 130rem;
      }

      /* Subtítulo */
      .large-header-subtitle {
        text-align: center;
        margin: 0;
        font-weight: 400;
        font-size: 12rem;
        color: #4f81ee;
      }

      /* Texto de la dirección/aviso al final del header */
      .large-header-addres {
        position: relative;
        top: -14rem;
        text-align: center;
        font-size: 8rem;
        color: #3f3f46;
      }
    </style>

    <!--small-header Classes---------------------------------------------------------------------------->
    <style>
      /* Contenedor principal del header */
      .small-header-container {
        position: relative;
        width: 100%;
        height: 36rem;
      }

      /* Área que contendrá el logo y los títulos */
      .small-header-background {
        display: flex;
        flex-direction: row;
        justify-content: space-between;
        height: 36rem;
        margin: 0 30rem;
        align-items: center;
      }

      /* Subtítulo */
      .small-header-subtitle {
        text-align: center;
        margin: 0;
        font-weight: 400;
        font-size: 10rem;
        color: #3f3f46;
        align-content: center;
      }

      /* Logo posicionado a la derecha */
      .small-header-logo {
        position: relative;
        height: 20rem;
        width: 103.333rem;
        align-content: center;
      }

      /* Línea inferior de color azul */
      .small-header-bottomLine {
        position: absolute;
        bottom: 0rem;
        background-color: #e4e4e7;
        height: 1rem;
        width: calc(100% - 60rem);
        margin: 0 30rem;
      }
    </style>

    <!--footer Classes---------------------------------------------------------------------------->
    <style>
      .footer-container {
        position: absolute;
        bottom: 0;
        width: 100%;
        height: 36rem;
        display: flex;
        flex-direction: column;
      }

      .footer-container > div {
        position: relative;
        width: 100%;
        height: 100%;
      }

      .footer-topLine {
        position: absolute;
        top: 0px;
        background-color: #508eeb;
        height: 1rem;
        width: calc(100% - 60rem);
        margin: 0 30rem;
      }

      .footer-text-container {
        display: flex;
        flex-direction: column;
        height: 100%;
        font-weight: 400;
        justify-content: space-evenly;
        color: #52525b;
      }

      .footer-date-printeOn {
        font-size: 10rem;
        margin-left: 30rem;
      }

      .footer-nameInitials {
        display: flex;
        flex-direction: row;
        font-size: 10rem;
        margin: 0 30rem;
        justify-content: space-between;
      }

      .footer-pageNum {
        margin-left: 30rem;
      }
    </style>

    <!-- PAGE 1 --------------------------------------------------------------------------------------------------------------------------------------------------------------------------->

    <div class="page">
      <!-- Header -->
      <header class="large-header-container">
        <!-- Línea superior azul -->
        <div class="large-header-topLine"></div>

        <!-- Contenedor principal del fondo, logo y texto -->
        <div class="large-header-background">
